ord beoordeeld als niet nuttig','Nothing here. Well done.'=>'Hier is niets. Goed gedaan.','Period'=>'Periode','Last 7 days'=>'Afgelopen 7 dagen','Last 30 days'=>'Afgelopen 30 dagen','Last 90 days'=>'Afgelopen 90 dagen','Last 12 months'=>'Afgelopen 12 maanden','%s%% answered by the assistant alone'=>'%s%% beantwoord door de assistent alleen','Handed to a person'=>'Overgedragen aan een persoon','median wait %s'=>'gemiddelde wachttijd %s','Tickets opened'=>'Geopende tickets','%d still open'=>'nog %d open','median · average %s'=>'mediaan · gemiddelde %s','Time to solve'=>'Oplostijd','median · %d solved'=>'mediaan · %d opgelost','Customer satisfaction'=>'Klanttevredenheid','%d ratings, average %s of 5'=>'%d beoordelingen, gemiddeld %s van de 5','SLA first reply met'=>'SLA eerste reactie behaald','%1$d due, %2$d missed'=>'%1$d openstaand, %2$d gemist','Assistant answers rated'=>'Door de assistent gegeven antwoorden beoordeeld','helpful / rated'=>'nuttig / beoordeeld','Chats and tickets per day'=>'Chats en tickets per dag','%1$d chats, %2$d tickets'=>'%1$d chats, %2$d tickets','Tickets answered'=>'Beantwoorde tickets','Replies'=>'Reacties','Rating'=>'Beoordeling','Top topics'=>'Populaire onderwerpen','Where tickets came from'=>'Waar tickets vandaan komen']];